package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.junit.jupiter.api.Test;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.FindAndModifyOptions;import org.springframework.data.mongodb.core.query.Query;import org.springframework.data.mongodb.core.query.Update;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class InventoryServiceTest {
 @Test void unavailableSeatCannotBeClaimedTwice(){SeatRepository repo=mock(SeatRepository.class);MongoTemplate mongo=mock(MongoTemplate.class);SeatService service=new SeatService(repo,mongo);when(mongo.findAndModify(any(Query.class),any(Update.class),any(FindAndModifyOptions.class),eq(Seat.class))).thenReturn(null);assertNull(service.claim("f1","4A","b1"));}
 @Test void availableSeatIsClaimedByAtomicConditionalUpdate(){SeatRepository repo=mock(SeatRepository.class);MongoTemplate mongo=mock(MongoTemplate.class);Seat seat=new Seat();seat.setStatus(Seat.Status.BOOKED);seat.setBookingId("b1");when(mongo.findAndModify(any(Query.class),any(Update.class),any(FindAndModifyOptions.class),eq(Seat.class))).thenReturn(seat);assertSame(seat,new SeatService(repo,mongo).claim("f1","4A","b1"));verify(mongo).findAndModify(any(Query.class),any(Update.class),any(FindAndModifyOptions.class),eq(Seat.class));}
 @Test void roomWithZeroAvailabilityCannotBeClaimed(){RoomRepository repo=mock(RoomRepository.class);MongoTemplate mongo=mock(MongoTemplate.class);RoomService service=new RoomService(repo,mongo);when(mongo.findAndModify(any(Query.class),any(Update.class),any(FindAndModifyOptions.class),eq(Room.class))).thenReturn(null);assertNull(service.claim("h1","DELUXE"));}
 @Test void availableRoomIsClaimedAtomicallyForRequestedQuantity(){RoomRepository repo=mock(RoomRepository.class);MongoTemplate mongo=mock(MongoTemplate.class);Room room=new Room();room.setAvailableQuantity(1);when(mongo.findAndModify(any(Query.class),any(Update.class),any(FindAndModifyOptions.class),eq(Room.class))).thenReturn(room);assertSame(room,new RoomService(repo,mongo).claim("h1","DELUXE",2));verify(mongo).findAndModify(any(Query.class),any(Update.class),any(FindAndModifyOptions.class),eq(Room.class));}
}
